export interface TrustGetResult {
  path: string;
  state: TrustState;
}

export interface TrustListResult {
  items: TrustedFolder[];
}

export interface TrustSetParams {
  decision: TrustDecision;
  path: string;
}

export type TrustState = "trusted" | "once" | "denied" | "unknown";

/**
 * One stored folder decision (`trust.json`, 08 §4). Revoke with
 * `trust.set {path, decision: "revoke"}`.
 */
export interface TrustedFolder {
  /** Approved project definitions (MCP servers, hooks) under this decision. */
  approvals?: number;
  /** RFC 3339. */
  decided_at: string;
  /** `trust` or `deny`. */
  decision: TrustDecision;
  /** Repository identity the decision is bound to, if any. */
  identity?: string | null;
  /** Canonical folder path. */
  path: string;
}

export interface TurnInterrupted {
  reason: InterruptReason;
  turn_id: string;
}

export interface TurnSettled {
  error?: ErrorInfo | null;
  status: TurnStatus;
  turn_id: string;
}

export interface TurnStarted {
  /** The admitted user message (or inbox item id until the store assigns messages). */
  message_id: string;
  resume?: boolean;
  turn_id: string;
}

export type TurnStatus = "completed" | "failed" | "cancelled" | "unknown";

export interface UnlockParams {
  passphrase: string;
}

export interface UpdateParams {
  active_leaf_id?: string | null;
  archived?: boolean | null;
  /** Per-chat provider code execution toggle (D35). */
  code_execution?: boolean | null;
  effort?: string | null;
  mode?: Mode | null;
  model?: string | null;
  pinned?: boolean | null;
  /** Move a Chat session into a project; `""` moves it out of its project. */
  project_id?: string | null;
  session_id: string;
  title?: string | null;
  /** Per-chat provider web search toggle (06 §8). */
  web_search?: boolean | null;
}

export interface UploadIdParams {
  upload_id: string;
}

export interface UploadIdResult {
  upload_id: string;
}

/** Token usage of a step or session. */
export interface Usage {
  cache_read_tokens?: number;
  cache_write_tokens?: number;
  input_tokens?: number;
  output_tokens?: number;
  reasoning_tokens?: number;
}

export type UsageGroup = "day" | "provider" | "model" | "project" | "unknown";

export interface UsageQueryParams {
  /** RFC 3339 date or date-time. */
  from: string;
  group_by: UsageGroup[];
  to: string;
}

export interface UsageQueryResult {
  rows: UsageRow[];
}

export interface UsageRow {
  /** Tokens spent on compaction (D34). */
  compaction_tokens?: number;
  cost: Cost;
  /** One value per `group_by` entry, in order. */
  keys: string[];
  usage: Usage;
}

export interface UsageUpdated {
  /** Context meter (D32). */
  context_tokens: number;
  context_window: number;
  cost: Cost;
  session: Usage;
}

/**
 * `notification`: something the desktop app should show as an OS notification
 * (e.g. "Genie needs your approval", 02 §7 step 2).
 */
export interface UserNotification {
  ask_id?: string | null;
  body: string;
  /** `genie://…` deep link. */
  link?: string | null;
  session_id?: string | null;
  title: string;
}

/**
 * `browser.viewport`: the size the Browser tab shows pages at, so the page fills the
 * panel (`Emulation.setDeviceMetricsOverride` on the session's tabs while headless).
 * Zoom is folded in by the client: a smaller CSS viewport at a larger `device_scale`.
 */
export interface ViewportParams {
  /** Device pixels per CSS pixel (the page's `devicePixelRatio`). */
  device_scale: number;
  height: number;
  session_id: string;
  /** CSS pixels. */
  width: number;
}

/** `workspace.snapshot`. */
export interface WorkspaceSnapshot {
  clients: ClientRef[];
  /** Asks waiting across all sessions (badge count). */
  pending_asks: number;
  sessions: SessionSummary[];
}

export type WorktreeAction = "merge" | "pr" | "keep" | "discard" | "unknown";

export type WorktreeChoice = "auto" | "new" | "none" | "unknown";

export interface WorktreeFinishParams {
  action: WorktreeAction;
  session_id: string;
}

/** `worktree.finish` result (additive: older clients read it as `{}`). */
export interface WorktreeFinishResult {
  /** The `genie/<slug>` branch was deleted. */
  branch_deleted?: boolean;
  merge_commit?: string | null;
  /** What happened, for the user (PR commands, why a branch was kept …). */
  message?: string;
  /** The worktree folder was removed. */
  removed?: boolean;
}
